func (l *Loop) sweepPlayUID(ctx context.Context) error {
	if l.cfg.PlayUID == 0 || l.cfg.PlaySupervisor == "" {
		return nil
	}
	for attempt := 0; attempt < 3; attempt++ {
		_ = l.runSweep(ctx) // helper -> kill(-1, SIGKILL) as the play uid
		left, err := processesOfUID(l.cfg.PlayUID) // scans /proc/*/status from the worker's own uid
		if err == nil && len(left) == 0 {
			return nil
		}
	}
	return fmt.Errorf("play uid %d still has live processes after the sweep", l.cfg.PlayUID)
}
